import sys
s = sys.stdin.read().rstrip('\r\n')
last = {c: i for i, c in enumerate(s)}
start = end = 0
res = []
for i, c in enumerate(s):
    end = max(end, last[c])
    if i == end:
        res.append(str(end - start + 1))
        start = i + 1
print(' '.join(res))
